#!/usr/bin/env python"""periodicity_QC_visualiser.py  ·  v2025‑07‑16============================================QC panels for birdsong detectors – now with clearer highlighting.Colours-------yellow (α = 0.45, drawn last) : periodicity_detected_song_timespink   (α = 0.25)             : amplitude_detected_song_timesblue   (α = 0.25)             : wiener_detected_song_timesred ‑‑                         : dashed file boundary"""from __future__ import annotationsimport argparse, jsonfrom pathlib import Pathimport numpy as npimport matplotlib.pyplot as pltimport matplotlib.patches as mpatchesimport soundfile as sffrom scipy.signal import spectrogramROW_DUR = 10.0                 # seconds per timeline row# ───────────────────────── small helpers ─────────────────────────def _draw_segment(ax, audio, sr, offset, dur, *, vmin=-90, vmax=-20):    if dur <= 0:        return    f, t, S = spectrogram(        audio[: int(round(dur * sr))],        fs=sr, nperseg=1024, noverlap=512,        scaling="spectrum", mode="magnitude",    )    S_db = 20 * np.log10(S + 1e-12)    ax.pcolormesh(offset + t, f, S_db,                  shading="auto", cmap="gray_r",                  vmin=vmin, vmax=vmax)def _highlight(ax, spans, pane_offset, seg_dur,               *, colour, alpha, zorder):    for s, e in spans:        if e <= 0 or s >= seg_dur:            continue        ax.axvspan(pane_offset + max(s, 0),                   pane_offset + min(e, seg_dur),                   color=colour, alpha=alpha, zorder=zorder)def _save_legend(output_dir: Path):    fig, ax = plt.subplots(figsize=(4, 2))    ax.axis("off")    handles = [        mpatches.Patch(color="yellow", alpha=0.45,                       label="Periodicity span"),        mpatches.Patch(color="pink",   alpha=0.25,                       label="Amplitude span"),        mpatches.Patch(color="blue",   alpha=0.25,                       label="Wiener‑entropy span"),        plt.Line2D([0], [0], color="red", lw=2, ls="--",                   label="File boundary"),    ]    ax.legend(handles=handles, frameon=False, loc="center")    fig.savefig(output_dir / "periodicity_QC_key.png",                dpi=300, bbox_inches="tight")    plt.close(fig)    print(f"[INFO] Saved {output_dir/'periodicity_QC_key.png'}")# ───────────────────── main figure builder ─────────────────────def build_QC_panels(json_path, output_dir, *,                    sr: int = 44100, rows_per_fig: int = 6):    json_path, output_dir = Path(json_path), Path(output_dir)    output_dir.mkdir(parents=True, exist_ok=True)    with json_path.open() as f:        recs_all = json.load(f)    recs = [r for r in recs_all            if r.get("metrics", {})                 .get("periodicity_detected_song_times")]    if not recs:        print("[WARN] No recordings with periodicity detections found.")        return    legend_done = False    rec_idx, rec_progress, fig_no = 0, 0.0, 1    while rec_idx < len(recs):        fig, axes = plt.subplots(            rows_per_fig, 1,            figsize=(10, 2 * rows_per_fig),            sharex=True, constrained_layout=True,        )        axes = np.atleast_1d(axes)        for ax in axes:            if rec_idx >= len(recs):                ax.axis("off"); continue            offset, titles = 0.0, []            while offset < ROW_DUR and rec_idx < len(recs):                rec      = recs[rec_idx]                met      = rec["metrics"]                wav_path = Path(rec["file_path"])                # load clip once per recording                if rec_progress == 0.0:                    audio_full, sr_file = sf.read(wav_path)                    if audio_full.ndim > 1:                        audio_full = audio_full.mean(axis=1)                    if sr_file != sr:                        print(f"[WARN] {wav_path.name}: "                              f"sr {sr_file} != {sr}; using {sr_file}")                        sr = sr_file                remaining = rec["duration_seconds"] - rec_progress                seg_dur   = min(remaining, ROW_DUR - offset)                # slice audio                start_samp = int(round(rec_progress * sr))                seg_audio  = audio_full[start_samp:                                        start_samp + int(round(seg_dur * sr))]                _draw_segment(ax, seg_audio, sr, offset, seg_dur)                shift = rec_progress                # draw PINK & BLUE first (lower z‑orders) …                _highlight(ax, [(s-shift, e-shift) for s, e in                                met["amplitude_detected_song_times"]],                           offset, seg_dur,                           colour="pink", alpha=0.25, zorder=4)                _highlight(ax, [(s-shift, e-shift) for s, e in                                met["wiener_detected_song_times"]],                           offset, seg_dur,                           colour="blue", alpha=0.25, zorder=5)                # … then YELLOW on top                _highlight(ax, [(s-shift, e-shift) for s, e in                                met["periodicity_detected_song_times"]],                           offset, seg_dur,                           colour="yellow", alpha=0.45, zorder=6)                rec_progress += seg_dur                offset       += seg_dur                finished = abs(rec_progress - rec["duration_seconds"]) < 1e-6                if finished:                    ax.axvline(offset, color="red", ls="--",                               lw=1.0, zorder=7)                    titles.append(wav_path.name)                    rec_idx     += 1                    rec_progress = 0.0            ax.set_xlim(0, ROW_DUR)            ax.set_ylim(0, 10_000)            ax.set_yticks([0, 2500, 5000, 7500, 10_000])            ax.set_ylabel("Freq [Hz]")            ax.tick_params(labelsize=8)            if titles:                ax.set_title(" + ".join(titles), fontsize=9, pad=4)        axes[-1].set_xlabel("Time [s]")        fig.suptitle(f"Periodicity QC panel {fig_no}", fontsize=12)        out_png = output_dir / f"periodicity_QC_panel_{fig_no:03d}.png"        fig.savefig(out_png, dpi=300)        plt.close(fig)        print(f"[INFO] Saved {out_png}")        if not legend_done:            _save_legend(output_dir); legend_done = True        fig_no += 1# ────────────────────────── CLI entry ──────────────────────────if __name__ == "__main__":    ap = argparse.ArgumentParser(        description="Visual QC for periodicity song detector.")    ap.add_argument("--json_path",  required=True, type=str)    ap.add_argument("--output_dir", required=True, type=str)    ap.add_argument("--sr",  default=44100, type=int)    ap.add_argument("--rows", default=6,  type=int, dest="rows_per_fig",                    help="Rows per figure.")    args = ap.parse_args()    build_QC_panels(args.json_path, args.output_dir,                    sr=args.sr, rows_per_fig=args.rows_per_fig)